def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Initial cooperation phase
    if n < 5:
        return 'C'

    # Extract history details
    my_last, opp_last = history[-1]

    # Calculate overall statistics
    opp_c_total = sum(1 for a, b in history if b == 'C')
    opp_defect_rate = 1.0 - (opp_c_total / float(n))

    # Check recent behavior (last 10 rounds or all if fewer)
    lookback = min(10, n)
    recent_hist = history[-lookback:]
    recent_opp_c = sum(1 for a, b in recent_hist if b == 'C')
    recent_defect_count = lookback - recent_opp_c

    # Streak detection
    streak_len = 0
    if opp_last == 'D':
        for i in range(n-1, -1, -1):
            if history[i][1] == 'D':
                streak_len += 1
            else:
                break
    elif opp_last == 'C':
        for i in range(n-1, -1, -1):
            if history[i][1] == 'C':
                streak_len += 1
            else:
                break

    # Strategy Core

    # 1. Exploit sustained defectors
    if streak_len >= 4:
        # If opponent is on a long defection streak, defect to punish/avoid exploitation
        # But occasionally test forgiveness if the streak isn't infinite
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # 2. Handle high overall defect rate
    if opp_defect_rate > 0.6:
        # Opponent is likely uncooperative. Stick to D mostly, but probe C occasionally
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # 3. Standard Tit-for-Tat with noise handling and slight forgiveness
    # If opponent just cooperated, we cooperate
    if opp_last == 'C':
        # Even if they cooperated, if recent defects were high, maybe be cautious?
        # But generally reciprocate C
        return 'C'

    # If opponent just defected:
    if opp_last == 'D':
        # We consider retaliating. 
        # If this was an isolated defect (streak_len == 1), forgive more often.
        # If it's part of a pattern, retaliate.

        if streak_len == 1:
            # Isolated defection. High probability of cooperation next turn to encourage recovery
            # unless the opponent has been historically very bad.
            if opp_defect_rate < 0.4:
                return 'C'
            else:
                return 'D'

        elif streak_len <= 3:
            # Short burst of defections. Mix strategy based on RNG to confuse pure TFT opponents
            # and avoid getting stuck in DD loops with noisy TFTs.
            r = rng.random()
            if r < 0.5:
                return 'D' # Retaliate
            else:
                return 'C' # Forgive

        else:
            # Long streak handled by rule 1, but safety net:
            return 'D'

    # Default fallback
    return 'C'
